@namespace sv_8e0807ff14044dadb776199cf3c247b1.Components.Pages.Apply

<nav class="mb-4" aria-label="Application progress">
    <ol class="d-flex list-unstyled justify-content-between step-indicator">
        @for (int i = 0; i < StepNames.Count; i++)
        {
            var stepIndex = i;
            var status = stepIndex == CurrentStep ? "active"
                       : CompletedSteps.Contains(stepIndex) ? "completed"
                       : "pending";
            <li class="step-item @status text-center flex-fill"
                role="button"
                @onclick="() => HandleStepClick(stepIndex)">
                <div class="step-circle mx-auto mb-1 rounded-circle d-flex align-items-center justify-content-center @GetCircleClass(status)">
                    @if (status == "completed")
                    {
                        <span>&#10003;</span>
                    }
                    else
                    {
                        <span>@(stepIndex + 1)</span>
                    }
                </div>
                <small class="d-none d-sm-block">@StepNames[stepIndex]</small>
            </li>
        }
    </ol>
</nav>

<style>
    .step-circle {
        width: 36px;
        height: 36px;
        font-size: 0.9rem;
        font-weight: bold;
        transition: all 0.2s;
    }
    .step-circle.bg-primary { color: white; }
    .step-circle.bg-success { color: white; }
    .step-circle.bg-secondary { color: white; opacity: 0.5; }
    .step-item.completed { cursor: pointer; }
    .step-item.pending { cursor: default; }
    .step-item.active { cursor: default; }
</style>

@code {
    [Parameter, EditorRequired] public int CurrentStep { get; set; }
    [Parameter, EditorRequired] public HashSet<int> CompletedSteps { get; set; } = new();
    [Parameter, EditorRequired] public List<string> StepNames { get; set; } = new();
    [Parameter] public EventCallback<int> OnStepClicked { get; set; }

    private string GetCircleClass(string status) => status switch
    {
        "active" => "bg-primary",
        "completed" => "bg-success",
        _ => "bg-secondary"
    };

    private async Task HandleStepClick(int step)
    {
        if (CompletedSteps.Contains(step))
        {
            await OnStepClicked.InvokeAsync(step);
        }
    }
}

@namespace sv_8e0807ff14044dadb776199cf3c247b1.Components.Pages.Apply
@using sv_8e0807ff14044dadb776199cf3c247b1.Models

<div class="card mb-3">
    <div class="card-body">
        <div class="d-flex justify-content-between align-items-center mb-3">
            <h6 class="card-title mb-0">Reference @Index</h6>
            @if (ShowRemove)
            {
                <button type="button" class="btn btn-outline-danger btn-sm" @onclick="OnRemove">Remove</button>
            }
        </div>
        <div class="row g-3">
            <div class="col-md-6">
                <label class="form-label">Name</label>
                <input type="text" class="form-control" @bind="Reference.Name" />
            </div>
            <div class="col-md-6">
                <label class="form-label">Relationship</label>
                <input type="text" class="form-control" @bind="Reference.Relationship" />
            </div>
            <div class="col-md-6">
                <label class="form-label">Email</label>
                <input type="email" class="form-control" @bind="Reference.Email" />
            </div>
            <div class="col-md-6">
                <label class="form-label">Phone</label>
                <input type="tel" class="form-control" @bind="Reference.Phone" />
            </div>
        </div>
    </div>
</div>

@code {
    [Parameter, EditorRequired] public ReferenceModel Reference { get; set; } = default!;
    [Parameter] public int Index { get; set; }
    [Parameter] public bool ShowRemove { get; set; }
    [Parameter] public EventCallback OnRemove { get; set; }
}

@namespace sv_8e0807ff14044dadb776199cf3c247b1.Components.Pages.Apply
@using sv_8e0807ff14044dadb776199cf3c247b1.Models
@using sv_8e0807ff14044dadb776199cf3c247b1.Services

<h4 class="mb-3">Personal Information</h4>

@if (!string.IsNullOrEmpty(errorMessage))
{
    <div class="alert alert-danger">@errorMessage</div>
}

<div class="row g-3">
    <div class="col-md-6">
        <label class="form-label">Full Name <span class="text-danger">*</span></label>
        <input type="text" class="form-control" @bind="Model.FullName" />
    </div>
    <div class="col-md-6">
        <label class="form-label">Email <span class="text-danger">*</span></label>
        <input type="email" class="form-control @(emailInvalid ? "is-invalid" : "")" @bind="Model.Email" />
        @if (emailInvalid)
        {
            <div class="invalid-feedback">Please enter a valid email address.</div>
        }
    </div>
    <div class="col-md-6">
        <label class="form-label">Phone <span class="text-danger">*</span></label>
        <input type="tel" class="form-control" @bind="Model.Phone" />
    </div>
    <div class="col-md-6">
        <label class="form-label">Address <span class="text-danger">*</span></label>
        <input type="text" class="form-control" @bind="Model.Address" />
    </div>
</div>

<div class="d-flex justify-content-end mt-4">
    <button class="btn btn-primary" @onclick="HandleNext" disabled="@isValidating">
        @if (isValidating)
        {
            <span class="spinner-border spinner-border-sm me-1" role="status"></span>
        }
        Next
    </button>
</div>

@code {
    [Parameter, EditorRequired] public PersonalInfoModel Model { get; set; } = default!;
    [Parameter] public EventCallback OnNext { get; set; }
    [Inject] private IApplicationService ApplicationService { get; set; } = default!;

    private string? errorMessage;
    private bool emailInvalid;
    private bool isValidating;

    private async Task HandleNext()
    {
        errorMessage = null;
        emailInvalid = false;

        if (string.IsNullOrWhiteSpace(Model.FullName) ||
            string.IsNullOrWhiteSpace(Model.Email) ||
            string.IsNullOrWhiteSpace(Model.Phone) ||
            string.IsNullOrWhiteSpace(Model.Address))
        {
            errorMessage = "All fields are required.";
            return;
        }

        isValidating = true;
        try
        {
            var valid = await ApplicationService.ValidateEmailAsync(Model.Email);
            if (!valid)
            {
                emailInvalid = true;
                errorMessage = "The email address could not be validated.";
                return;
