+++ b/tmp/sv-8e0807ff14044dadb776199cf3c247b1/Components/Pages/Apply/StepIndicator.razor
@@ -1,0 +1,67 @@
+@namespace sv_8e0807ff14044dadb776199cf3c247b1.Components.Pages.Apply
+
+<nav class="mb-4" aria-label="Application progress">
+    <ol class="d-flex list-unstyled justify-content-between step-indicator">
+        @for (int i = 0; i < StepNames.Count; i++)
+        {
+            var stepIndex = i;
+            var status = stepIndex == CurrentStep ? "active"
+                       : CompletedSteps.Contains(stepIndex) ? "completed"
+                       : "pending";
+            <li class="step-item @status text-center flex-fill"
+                role="button"
+                @onclick="() => HandleStepClick(stepIndex)">
+                <div class="step-circle mx-auto mb-1 rounded-circle d-flex align-items-center justify-content-center @GetCircleClass(status)">
+                    @if (status == "completed")
+                    {
+                        <span>&#10003;</span>
+                    }
+                    else
+                    {
+                        <span>@(stepIndex + 1)</span>
+                    }
+                </div>
+                <small class="d-none d-sm-block">@StepNames[stepIndex]</small>
+            </li>
+        }
+    </ol>
+</nav>
+
+<style>
+    .step-circle {
+        width: 36px;
+        height: 36px;
+        font-size: 0.9rem;
+        font-weight: bold;
+        transition: all 0.2s;
+    }
+    .step-circle.bg-primary { color: white; }
+    .step-circle.bg-success { color: white; }
+    .step-circle.bg-secondary { color: white; opacity: 0.5; }
+    .step-item.completed { cursor: pointer; }
+    .step-item.pending { cursor: default; }
+    .step-item.active { cursor: default; }
+</style>
+
+@code {
+    [Parameter, EditorRequired] public int CurrentStep { get; set; }
+    [Parameter, EditorRequired] public HashSet<int> CompletedSteps { get; set; } = new();
+    [Parameter, EditorRequired] public List<string> StepNames { get; set; } = new();
+    [Parameter] public EventCallback<int> OnStepClicked { get; set; }
+
+    private string GetCircleClass(string status) => status switch
+    {
+        "active" => "bg-primary",
+        "completed" => "bg-success",
+        _ => "bg-secondary"
+    };
+
+    private async Task HandleStepClick(int step)
+    {
+        if (CompletedSteps.Contains(step))
+        {
+            await OnStepClicked.InvokeAsync(step);
+        }
+    }
+}
+

